import {CV_MATCH_ENABLED} from "./features.mjs";
import {field,language,t} from './i18n.mjs';
import {opportunityStatusLabel} from './opportunity.mjs';
import {researchUnits,sourcePortals,topicChoices,methodChoices,suggestFromText,cvFileText} from './explore.mjs?v=06';
const $=s=>document.querySelector(s),node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const button=(text,fn,cls)=>{const n=node('button',text,cls);n.type='button';n.onclick=fn;return n;};
const link=(text,url)=>{const n=node('a',text,'external-link');n.href=url;n.target='_blank';n.rel='noopener noreferrer';return n;};
export function setupJourney({getJobs,getOfficialJobs,applyProfile,showJob,matchJob}){
 let mode='jobs',readSerial=0;const compare=new Set(),extra=$('#extra-view'),layout=$('.layout');
 function leave(){mode='jobs';extra.hidden=true;layout.hidden=false;for(const id of ['groups-tab','sources-tab'])$('#'+id).classList.remove('current');}
 function view(which,title,description){mode=which;layout.hidden=true;extra.hidden=false;extra.replaceChildren(node('h2',title),node('p',description,'section-intro'));$('#discover').classList.remove('current');$('#saved-tab').classList.remove('current');for(const id of ['groups-tab','sources-tab'])$('#'+id).classList.toggle('current',id===which+'-tab');}
 const dialog=node('dialog');dialog.id='guide-dialog';const head=node('div',undefined,'dialog-header');head.append(node('h2','还没确定方向？也可以开始。'),button('×',()=>dialog.close()));head.lastChild.setAttribute('aria-label','关闭引导');dialog.append(head);
 const intro=node('p','不必先知道研究兴趣。可以从做过的课程、项目和方法开始，选择愿意探索的方向；这不是职业测评。','form-note');dialog.append(intro);
 const cvPanel=node('section',undefined,'cv-panel');cvPanel.append(node('h3','可选：让简历帮你起步'));
 const cvLabel=node('label','选择简历文件（仅在本机读取）');const file=node('input');file.type='file';file.accept='.pdf,.docx,.txt,.md';file.id='cv-file';cvLabel.append(file);cvPanel.append(cvLabel,node('p','支持文字版 PDF / DOCX / TXT，最大 5 MB，PDF 最多 20 页。扫描件需先在本机识别文字。原文不上传、不写入浏览器存储。','help'));
 const rawLabel=node('label','或粘贴简历中的教育、项目与技能文字');const raw=node('textarea');raw.id='cv-text';raw.maxLength=100000;raw.rows=4;raw.placeholder='无需姓名、联系方式和未公开论文内容。';rawLabel.append(raw);cvPanel.append(rawLabel);const status=node('p','先提取候选标签，再由你确认；经历不自动等于兴趣。','help');status.setAttribute('role','status');cvPanel.append(status);
 const evidence=node('div',undefined,'cv-evidence');cvPanel.append(evidence);const topics=node('fieldset'),methods=node('fieldset');topics.append(node('legend','① 哪些主题愿意了解？（可跳过）'));methods.append(node('legend','② 已经使用过哪些方法？（请确认，不含学习意愿）'));
 function choices(parent,values,kind){for(const value of values){const label=node('label',undefined,'choice');const input=node('input');input.type='checkbox';input.value=value;input.dataset.kind=kind;label.append(input,document.createTextNode(value));parent.append(label);}}
 choices(topics,topicChoices,'topics');choices(methods,methodChoices,'methods');
 const extract=()=>{try{const found=suggestFromText(raw.value);for(const c of dialog.querySelectorAll('input[data-kind]')){c.checked=false;c.closest('label').classList.toggle('suggested',found[c.dataset.kind].includes(c.value));c.closest('label').hidden=!found[c.dataset.kind].includes(c.value);}evidence.replaceChildren(node('h4','文本线索分类 · 不是能力或资格认定'));for(const e of found.evidence||[]){evidence.append(node('p',t(e.label)+' · '+({experience:'经历候选，待本人确认',interest:'学习兴趣，不计为已有技能',absent:'明确否定，不纳入技能',uncertain:'本人承担工作不明，不纳入技能',candidate:'关键词候选，需本人确认'}[e.state]||'待确认'),'help'));}status.textContent='识别到 '+found.topics.length+' 个主题、'+found.methods.length+' 个方法。下方高亮是候选项，请勾选愿意探索的标签；不会自动选择。';raw.value='';file.value='';}catch(e){status.textContent=e.message;}};cvPanel.append(button('从文本提取候选标签',extract,'primary-action'));const expand=button('显示所有方向与方法',()=>{for(const label of dialog.querySelectorAll('.choice'))label.hidden=false;});dialog.append(cvPanel,topics,methods,expand);
 const customLabel=node('label','③ 词表里没有？补充主题（逗号分隔，可留空）'),custom=node('input');custom.maxLength=500;customLabel.append(custom);dialog.append(customLabel);
 const foot=node('div',undefined,'form-actions');foot.append(button('先看全部岗位',()=>{dialog.close();leave();$('#reset').click();$('#discover').click();}),button('预览相关机会（不保存档案）',()=>{const selected=kind=>[...dialog.querySelectorAll('input[data-kind="'+kind+'"]:checked')].map(x=>x.value);const t=[...selected('topics'),...custom.value.split(/[,，]/).map(s=>s.trim()).filter(Boolean)];if(!t.length&&!selected('methods').length){status.textContent='可先不设置匹配，点击“先看全部岗位”。';return;}if(applyProfile({topics:t.join(', '),methods:selected('methods').join(', ')},{persist:false})){dialog.close();leave();$('#discover').click();}},'primary-action'));dialog.append(foot);document.body.append(dialog);
 file.onchange=async()=>{const f=file.files[0];if(!f)return;const serial=++readSerial;status.textContent='正在本机读取…';try{const text=await cvFileText(f);if(serial!==readSerial||!dialog.open)return;raw.value=text;extract();}catch(e){if(serial===readSerial&&dialog.open)status.textContent=e.message;}finally{if(serial===readSerial)file.value='';}};
 dialog.addEventListener('close',()=>{readSerial++;raw.value='';file.value='';custom.value='';evidence.replaceChildren();for(const label of dialog.querySelectorAll('.suggested'))label.classList.remove('suggested');for(const c of dialog.querySelectorAll('input[data-kind]')){c.checked=false;c.closest('label').hidden=false;}status.textContent='原文已从当前表单清空。仅经你确认的概括标签会写入本地匹配档案。';});
 function guide(withCV=false){if(!CV_MATCH_ENABLED)return;dialog.showModal();if(withCV)file.focus();}
 $('#guide-start').onclick=()=>guide();$('#cv-start').onclick=()=>guide(true);$('#profile-guide').onclick=()=>{$('#profile-dialog').close();guide();};
 function groups(){
  view('groups','研究组与研究单位','认识研究团队，找到让你好奇的问题。');
  const searchLabel=node('label','搜索名称、大学或主题'),search=node('input');search.type='search';search.placeholder='例如：治理、传播、UvA';searchLabel.append(search);extra.append(searchLabel);const list=node('div',undefined,'unit-grid');extra.append(list);
  function draw(){list.replaceChildren();const q=search.value.trim().toLowerCase();for(const unit of researchUnits.filter(u=>[u.name,u.institution,...u.topics].join(' ').toLowerCase().includes(q))){const card=node('article',undefined,'unit-card');card.append(node('span',language==='en'?'Research · Netherlands':unit.kind+' · '+unit.country,'tag'),node('h3',language==='en'?({aissr:'Amsterdam Institute for Social Science Research',ivir:'Institute for Information Law','leiden-pa':'Institute of Public Administration',ascor:'Amsterdam School of Communication Research','youth-media':'Youth & Media Entertainment',infrapax:'Infra-PaX'}[unit.id]||unit.name):unit.name),node('p',language==='en'?(unit.id==='leiden-pa'?'Leiden University':unit.id==='infrapax'?'TU Delft':'University of Amsterdam'):unit.institution,'unit-institution'),node('p',language==='en'?({aissr:'Explore social science research projects and doctoral training.',ivir:'Research on information law, platform regulation and digital technologies.','leiden-pa':'Public administration, governance and sustainability transitions.',ascor:'Discover communication research and doctoral projects.','youth-media':'Research on young people, media and entertainment.',infrapax:'Digital and sustainable transitions in infrastructure.'}[unit.id]||'Explore the research on the official website.'):unit.summary),node('p',language==='en'?'Explore the team and its research on the official website.':unit.evidence,'help'));const related=getOfficialJobs().filter(j=>unit.jobIds.includes(j.id)&&!matchJob(j).expired);card.append(node('strong','本库关联 '+related.length+' 条未过期快照'));for(const j of related)card.append(button(field(j,'title')+' ↗',()=>showJob(j,matchJob(j)),'unit-job'));
   card.append(link('打开官方证据页 ↗',unit.url));const checklist=node('details');checklist.append(node('summary','如何进一步了解这个组？'));const ul=node('ul');for(const text of ['阅读近年的研究与博士论文，核对与你相关的方法。','在官方团队页核对导师、共同指导及博士生身份。','询问合同期限、教学工作量、经费保障与延期安排。','经对方同意，向在读或毕业生了解指导频率和支持。','毕业去向需明确样本、时间窗和缺失，不能用少量个例推算。'])ul.append(node('li',text));checklist.append(ul);card.append(checklist);list.append(card);}if(!list.childElementCount)list.append(node('p','当前目录没有命中；这不代表没有相关研究组。'));}search.oninput=draw;draw();
 }
 function sources(){view('sources','扩大搜索，不靠虚增数字','本库没有覆盖的方向，可直接去官方入口。外部岗位不计入本库数量；打开原站后，适用对方的隐私政策。');for(const source of sourcePortals){const card=node('article',undefined,'unit-card');card.append(node('h3',language==='en'?({ '哥本哈根大学博士招聘':'University of Copenhagen','UvA 官方招聘':'University of Amsterdam','TU Delft 官方招聘':'TU Delft','维也纳大学博士岗位':'University of Vienna'}[source.name]||source.name):source.name),node('p',language==='en'?'Official research careers portal':source.region),node('p',language==='en'?'Browse current opportunities and full application requirements on the official website.':source.note),link('去官方入口 ↗',source.url));extra.append(card);}}
 $('#groups-tab').onclick=groups;$('#sources-tab').onclick=sources;
 function compareJobs(){const selected=getJobs().filter(j=>compare.has(j.id));if(!selected.length)return;const d=node('dialog');const heading=node('div',undefined,'dialog-header');heading.append(node('h2','岗位并排核对'),button('×',()=>d.close()));heading.lastChild.setAttribute('aria-label','关闭对比');d.append(heading,node('p','这是证据对照，不是申请资格判断。未编码和未填写都不会被视为不符合。','form-note'));const grid=node('div',undefined,'compare-grid');for(const j of selected){const c=node('article',undefined,'unit-card');c.append(node('h3',field(j,'title')));for(const [key,value] of [['机构',field(j,'institution')],['截止日期',j.deadline],['当前状态',opportunityStatusLabel(j,'zh')],['经费／薪资',field(j,'salary')],['语言',field(j,'language')],['要求',field(j,'requirements')],['特别限制',field(j,'caution')]]){c.append(node('strong',key),node('p',value));}const m=matchJob(j);c.append(node('strong','主题／方法交集'),node('p',m.overlap.join('、')||'未设置或暂无关键词命中'),link('核对官方原帖 ↗',j.url));grid.append(c);}d.append(grid);d.style.width='min(1100px,96vw)';document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();}
 $('#compare-open').onclick=compareJobs;
 function updateComparison(){const available=new Set(getJobs().map(j=>j.id));for(const id of compare)if(!available.has(id))compare.delete(id);$('#compare-open').textContent='对比已选（'+compare.size+'/3）';$('#compare-open').disabled=!compare.size;}
 function attachComparison(card,j){const label=node('label',undefined,'compare-choice'),c=node('input');c.type='checkbox';c.checked=compare.has(j.id);c.onchange=()=>{if(c.checked&&compare.size>=3){c.checked=false;$('#compare-status').textContent='最多对比 3 条，请先取消一条。';return;}if(c.checked)compare.add(j.id);else compare.delete(j.id);$('#compare-status').textContent='对比选择只保留在当前页面，不上传。';updateComparison();};label.append(c,document.createTextNode('加入对比'));card.querySelector('.job-side').append(label);}
 window.addEventListener('languagechange',()=>{if(mode==='groups')groups();else if(mode==='sources')sources();});return {leave,attachComparison,updateComparison,guide};
}
